"""Генерирует app/src/main/assets/questions.json.
Формат вопроса: category, question, arabic (необязательно), options (4 шт.), answer (индекс верного), explanation.
Перед публикацией вопросы стоит проверить у знающего человека (имама, преподавателя)."""
import json, pathlib

Q = []
def q(cat, question, options, answer, explanation, arabic=None):
    item = {"category": cat, "question": question, "options": options, "answer": answer, "explanation": explanation}
    if arabic: item["arabic"] = arabic
    Q.append(item)

